using System;
using System.Buffers;
using System.Runtime;
using System.Runtime.CompilerServices;
using System.Text;

namespace RuntimeGCDemo
{
    class Program
    {
        static readonly byte[] _longLived = new byte[1024]; // Gen 2 常驻

        static void Main()
        {
            DemonstrateGenerations();
            DemonstrateSpanVsSubstring();
            DemonstrateArrayPool();
            DemonstrateGCMode();
        }

        // 1. 分代提升演示
        static void DemonstrateGenerations()
        {
            object obj = new object();
            Console.WriteLine($"分配后: Gen {GC.GetGeneration(obj)}");
            // Gen 0

            GC.Collect(0);
            GC.WaitForPendingFinalizers();
            Console.WriteLine($"Gen 0 回收后: Gen {GC.GetGeneration(obj)}");
            // Gen 1

            GC.Collect(1);
            GC.WaitForPendingFinalizers();
            Console.WriteLine($"Gen 1 回收后: Gen {GC.GetGeneration(obj)}");
            // Gen 2

            Console.WriteLine($"总内存: {GC.GetTotalMemory(false):N0} bytes");
            Console.WriteLine($"Gen 0 回收次数: {GC.CollectionCount(0)}");
            Console.WriteLine($"Gen 1 回收次数: {GC.CollectionCount(1)}");
            Console.WriteLine($"Gen 2 回收次数: {GC.CollectionCount(2)}");
        }

        // 2. Span 零分配切片 vs Substring 分配
        static void DemonstrateSpanVsSubstring()
        {
            const string text = "Hello, World! This is a benchmark test.";
            const int iterations = 1_000_000;

            // Substring: 每次分配新 string
            long before = GC.GetTotalMemory(true);
            for (int i = 0; i < iterations; i++)
            {
                string sub = text.Substring(7, 5); // 分配新字符串
                Consume(sub);
            }
            long substringAlloc = GC.GetTotalMemory(false) - before;

            // Span.Slice: 零分配
            before = GC.GetTotalMemory(true);
            for (int i = 0; i < iterations; i++)
            {
                ReadOnlySpan<char> span = text.AsSpan(7, 5); // 零分配视图
                Consume(span.ToString()); // 仅用于演示，实际应直接用 span
            }
            long spanAlloc = GC.GetTotalMemory(false) - before;

            Console.WriteLine($"Substring 分配: {substringAlloc:N0} bytes");
            Console.WriteLine($"Span 分配:     {spanAlloc:N0} bytes");
        }

        // 3. ArrayPool 大缓冲复用
        static void DemonstrateArrayPool()
        {
            var pool = ArrayPool<byte>.Shared;

            // 不用池: 每次 new byte[65536]，超过 85KB 直接进 LOH
            long before = GC.GetTotalMemory(true);
            for (int i = 0; i < 1000; i++)
            {
                byte[] buf = new byte[85_001]; // LOH 对象
                buf[0] = 1;
            }
            long noPoolAlloc = GC.GetTotalMemory(false) - before;

            // 用池: 复用数组
            before = GC.GetTotalMemory(true);
            for (int i = 0; i < 1000; i++)
            {
                byte[] buf = pool.Rent(85_001); // 复用，不产生新分配
                buf[0] = 1;
                pool.Return(buf, clearArray: false);
            }
            long poolAlloc = GC.GetTotalMemory(false) - before;

            Console.WriteLine($"不用池 LOH 分配: {noPoolAlloc:N0} bytes");
            Console.WriteLine($"ArrayPool 复用:  {poolAlloc:N0} bytes");
        }

        // 4. GC 模式查询
        static void DemonstrateGCMode()
        {
            Console.WriteLine($"服务器 GC: {GCSettings.IsServerGC}");
            Console.WriteLine($"延迟模式: {GCSettings.LatencyMode}");
            // 可在 runtimeconfig.json 配置:
            // { "runtimeOptions": { "configProperties": { "System.GC.Server": true } } }
            // 或环境变量 DOTNET_gcServer=1
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        static void Consume<T>(T value) { }
    }
}
